    def __init__(self):
        super().__init__("clamp_stddev")

    def typecheck(self, args):
        if len(args) != 2:
            raise _EErr(f"expected 2 arguments, got {len(args)}")
        x_t = args[0].type
        eps_t = args[1].type
        if not (x_t.is_real_scalar() and eps_t.is_real_scalar()):
            raise _EErr(
