#
# This implements the same computation as PolyBench's correlation.c:
#   1. Compute column means.
#   2. Compute column standard deviations.
#   3. Center and normalize the data.
#   4. Compute the correlation matrix.
#
# The implementation is slightly reorganized to improve data locality:
#   - Mean and stddev are computed using row-major sweeps over data.
#   - The correlation accumulation is organized with the sample (k) loop
#     outermost, so each data row is reused while computing many pairs.
#   - sqrt(float_n) is computed once and reused.
# ---------------------------------------------------------------------------

@proc
def kernel_correlation(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    corr: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
    stddev: DATA_TYPE[m] @ DRAM,
):
