    # 3. Center and reduce the column vectors:
    #
    #    data[i,j] = (data[i,j] - mean[j]) / (sqrt(float_n) * stddev[j])
    #
    # We reuse sqrt_float_n instead of recomputing sqrt(float_n) each time.
    # The loop is row-major for good spatial locality on data.
