    #
    # We:
    #   - zero-initialize the corr matrix,
    #   - accumulate only the upper triangle (i < j) with k outermost,
    #   - then set the diagonal to 1.0 and mirror the upper triangle to the
    #     lower triangle.
    # This preserves the mathematical result while improving data reuse.
    # -----------------------------------------------------------------------

    # Zero-initialize entire correlation matrix
    for i in seq(0, m):
        for j in seq(0, m):
            corr[i, j] = 0.0

    # Accumulate upper triangle: k outermost to reuse each row of data
    for k in seq(0, n):
        for i in seq(0, m - 1):
            for j in seq(i + 1, m):
                corr[i, j] += data[k, i] * data[k, j]

    # Set diagonal to 1.0 and mirror upper triangle into lower triangle
    for i in seq(0, m):
        corr[i, i] = 1.0
        for j in seq(i + 1, m):
